// Validate auth, rate-limit, and route mode
const staticData = $getWorkflowStaticData('global');
const raw = $input.first().json;
const body = raw.body || raw;
const headers = raw.headers || {};

// --- Auth check ---
const provided = headers['x-voice-key'];
if (!staticData.voice_api_key || provided !== staticData.voice_api_key) {
  return [{ json: { routed: false, error: 'Unauthorized', statusCode: 401 } }];
}

// --- Rate limit: 10/min ---
const now = Date.now();
const window = 60000;
if (!staticData.voice_calls) staticData.voice_calls = [];
staticData.voice_calls = staticData.voice_calls.filter(t => t > now - window);
if (staticData.voice_calls.length >= 10) {
  return [{ json: { routed: false, error: 'Rate limited', retry_after: 60, statusCode: 429 } }];
}
staticData.voice_calls.push(now);

// --- Validate query ---
const query = (body.query || '').trim();
if (!query) {
  return [{ json: { routed: false, error: 'Missing required field: query', statusCode: 400 } }];
}

// --- Mode routing ---
let mode = (body.mode || 'auto').toLowerCase();
if (mode === 'auto') {
  const q = query.toLowerCase();
  const researchSignals = [
    'review', 'compare', 'latest', 'price', 'cost',
    'news', 'what is', 'who is', 'how much', 'find',
    'search', 'look up', 'current', 'recent', 'best',
    'recommend', 'rating', 'difference between'
  ];
  mode = researchSignals.some(s => q.includes(s)) ? 'research' : 'reasoning';
}

const sessionId = body.session_id || null;

// Build OpenClaw payloads as strings (Responses API: model + input + instructions)
const reasonPayload = JSON.stringify({
  model: 'openclaw',
  input: query,
  instructions: 'You are a voice reasoning assistant. Answer the user\'s question directly in 2-4 conversational sentences suitable for text-to-speech. No markdown, no bullet points, no special formatting. Be clear and helpful.'
});

return [{
  json: {
    routed: true,
    mode: mode,
    query: query,
    session_id: sessionId,
    openclaw_key: staticData.openclaw_key,
    tavily_key: staticData.tavily_key,
    reason_payload: reasonPayload
  }
}];

// Format TTS response — handle OpenClaw Responses API output
const item = $input.first().json;
const mode = $('Validate & Route').first().json.mode;

let answer = '';
try {
  // Responses API: output is array of content blocks
  const output = item.output || [];
  for (const block of output) {
    if (block.type === 'message') {
      for (const c of (block.content || [])) {
        if (c.type === 'output_text' || c.type === 'text') {
          answer += (c.text || '') + ' ';
        }
      }
    }
  }
  // Fallback: direct output_text at top level
  if (!answer.trim() && item.output_text) {
    answer = item.output_text;
  }
  // Fallback: choices format
  if (!answer.trim() && item.choices) {
    answer = item.choices[0].message.content || '';
  }
} catch (e) {
  answer = 'Sorry, I had trouble getting a response.';
}

// Strip markdown artifacts
answer = answer
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .replace(/#{1,6}\s/g, '')
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/`/g, '')
  .replace(/\n+/g, ' ')
  .trim();

// Truncate to ~4 sentences if somehow longer
const sentences = answer.match(/[^.!?]+[.!?]+/g) || [answer];
if (sentences.length > 4) {
  answer = sentences.slice(0, 4).join(' ').trim();
}

return [{
  json: {
    answer: answer,
    mode: mode,
    model: (item.model || 'unknown')
  }
}];
